import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('Lists & Keys', () => {
  test('Initially renders all 3 todos', async () => {
    const { container: root } = render(<App />);
    const items = root.querySelectorAll('#todo-list li');
if (items.length !== 3) throw new Error('Expected 3 items, found ' + items.length);
  });

  test('Each <li> has a data-id attribute', async () => {
    const { container: root } = render(<App />);
    const items = root.querySelectorAll('#todo-list li');
items.forEach(li => {
  if (!li.getAttribute('data-id')) throw new Error('Each <li> must have a data-id attribute');
});
  });

  test('Completed todo has className "done"', async () => {
    const { container: root } = render(<App />);
    const doneItem = root.querySelector('#todo-list li[data-id="1"]');
if (!doneItem) throw new Error('No li with data-id="1"');
if (!doneItem.classList.contains('done'))
  throw new Error('Completed todo should have class "done"');
  });

  test('Filter button shows only active todos', async () => {
    const { container: root } = render(<App />);
    const btn = root.querySelector('#filter-btn');
if (!btn) throw new Error('No #filter-btn found');
btn.click();
await tick();
const items = root.querySelectorAll('#todo-list li');
if (items.length !== 2) throw new Error('Expected 2 active items, found ' + items.length);
  });

  test('Count shows number of visible items', async () => {
    const { container: root } = render(<App />);
    const count = root.querySelector('#count');
if (!count) throw new Error('No #count element');
if (!count.textContent.includes('2')) throw new Error('Count should show 2 after filtering');
  });
});
